    data,
    isLoading,
    isError,
  } = useQuery({
    queryKey: ["lessons", currentPage],
    enabled: !!user?.uid,
    queryFn: async () => {
      const res = await axiosSecure.get(`/lessons?page=${currentPage}&limit=${limit}`);
      return res.data;
    },
    keepPreviousData: true,
  });

  if (isLoading || userLoading) return <Loading />;
